<script setup>
import { computed, onMounted, ref } from 'vue'
import { Shield, Users, Trophy, WalletCards, ArrowLeftRight, Landmark, Clock3, ExternalLink } from '@lucide/vue'
import { api } from '../../services/api';import { authStore } from '../../stores/auth';import { money, number, date } from '../../utils'
import LoadingBlock from '../../components/LoadingBlock.vue';import PageHeader from '../../components/PageHeader.vue';import EntityAvatar from '../../components/EntityAvatar.vue';import StatusBadge from '../../components/StatusBadge.vue';import RankMovement from '../../components/RankMovement.vue';import EmptyState from '../../components/EmptyState.vue'
const loading=ref(true),data=ref(null),isAdmin=computed(()=>authStore.isAdmin.value)
onMounted(async()=>{try{data.value=(await api.get('/dashboard')).data}finally{loading.value=false}})
const adminCards=computed(()=>data.value?[['Câu lạc bộ',data.value.summary.total_clubs,Shield,'text-primary'],['Cầu thủ',data.value.summary.total_players,Users,'text-green'],['Giải đang mở',data.value.summary.active_competitions,Trophy,'text-yellow'],['Quỹ FIFA',money(data.value.summary.fifa_balance,true),Landmark,'text-primary'],['Tiền CLB',money(data.value.summary.total_club_money,true),WalletCards,'text-green'],['Chuyển nhượng chờ',data.value.summary.pending_transfers,ArrowLeftRight,'text-yellow']]:[])
</script>
<template><div><PageHeader eyebrow="Command Center" :title="isAdmin?'Tổng quan hệ thống':'Tổng quan câu lạc bộ'" :description="isAdmin?'Theo dõi toàn bộ CLB, cầu thủ, giải đấu và dòng tiền trong một màn hình.':'Quản lý đội hình, tài chính, lịch thi đấu và vị thế của câu lạc bộ.'"/><LoadingBlock v-if="loading"/><template v-else-if="data"><template v-if="isAdmin"><div class="dashboard-stats"><article v-for="card in adminCards" :key="card[0]" class="glass stat-card"><component :is="card[2]" :size="19" :class="card[3]"/><div class="stat-value">{{ card[1] }}</div><div class="stat-label">{{ card[0] }}</div></article></div><div class="dashboard-grid"><section class="glass card"><div class="section-title"><div><span class="eyebrow">Chờ xử lý</span><h2>CLB đăng ký mới</h2></div><RouterLink to="/portal/clubs" class="btn btn-sm btn-ghost">Quản lý <ExternalLink :size="14"/></RouterLink></div><EmptyState v-if="!data.pendingClubs.length" title="Không có hồ sơ chờ duyệt"/><div v-else class="compact-list"><article v-for="club in data.pendingClubs" :key="club.id"><EntityAvatar :src="club.logo_url" :name="club.name" :size="38"/><div><b>{{ club.name }}</b><p>{{ club.code }} · {{ date(club.created_at,true) }}</p></div><StatusBadge status="PENDING"/></article></div></section><section class="glass card"><div class="section-title"><div><span class="eyebrow">Giải đấu</span><h2>Đang vận hành</h2></div><RouterLink to="/portal/competitions" class="btn btn-sm btn-ghost">Mở trung tâm</RouterLink></div><EmptyState v-if="!data.activeCompetitions.length"/><div v-else class="compact-list"><RouterLink v-for="c in data.activeCompetitions" :key="c.id" :to="`/portal/competitions/${c.id}`"><div class="competition-icon"><Trophy :size="18"/></div><div><b>{{ c.name }}</b><p>{{ c.season_name }} · {{ date(c.starts_on) }}</p></div><StatusBadge :status="c.status"/></RouterLink></div></section><section class="glass card ranking-panel"><div class="section-title"><div><span class="eyebrow">World ranking</span><h2>Top câu lạc bộ</h2></div></div><div class="rank-list"><article v-for="r in data.clubRanking" :key="r.club_id"><span class="rank">{{ r.rank_position }}</span><EntityAvatar :src="r.logo_url" :name="r.club_name" :size="34"/><div><b>{{ r.club_name }}</b><p>{{ number(r.score) }} điểm</p></div><RankMovement :change="r.rank_change" :previous="r.previous_rank"/></article></div></section><section class="glass card"><div class="section-title"><div><span class="eyebrow">Dòng tiền</span><h2>Giao dịch gần đây</h2></div></div><EmptyState v-if="!data.recentTransactions.length"/><div v-else class="transaction-list"><article v-for="t in data.recentTransactions" :key="t.id"><div class="tx-icon" :class="t.direction==='CREDIT'?'credit':'debit'"><WalletCards :size="17"/></div><div><b>{{ t.note||t.transaction_type }}</b><p>{{ t.wallet_code }} · {{ date(t.created_at,true) }}</p></div><strong :class="t.direction==='CREDIT'?'text-green':'text-red'">{{ t.direction==='CREDIT'?'+':'-' }}{{ money(t.amount,true) }}</strong></article></div></section></div></template><template v-else><section class="club-summary glass"><EntityAvatar :src="data.club.logo_url" :name="data.club.name" :size="80"/><div><span class="eyebrow">{{ data.club.code }}</span><h2>{{ data.club.name }}</h2><p>{{ data.club.short_name }}</p></div><div class="club-rank"><small>Hạng thế giới</small><b>#{{ data.ranking?.rank_position||'—' }}</b><RankMovement :change="data.ranking?.rank_change" :previous="data.ranking?.previous_rank"/></div></section><div class="grid-4" style="margin:20px 0"><article class="glass stat-card"><Users :size="18" class="text-primary"/><div class="stat-value">{{ data.playerStats.total_players }}</div><div class="stat-label">Cầu thủ</div></article><article class="glass stat-card"><WalletCards :size="18" class="text-green"/><div class="stat-value">{{ money(data.wallet?.balance,true) }}</div><div class="stat-label">Số dư CLB</div></article><article class="glass stat-card"><Landmark :size="18" class="text-yellow"/><div class="stat-value">{{ money(data.playerStats.total_salary,true) }}</div><div class="stat-label">Quỹ lương</div></article><article class="glass stat-card"><Trophy :size="18" class="text-primary"/><div class="stat-value">{{ data.achievements.length }}</div><div class="stat-label">Danh hiệu gần đây</div></article></div><div class="grid-2"><section class="glass card"><div class="section-title"><div><span class="eyebrow">Lịch thi đấu</span><h2>Trận sắp tới</h2></div></div><EmptyState v-if="!data.matches.length"/><div v-else class="compact-list"><article v-for="m in data.matches" :key="m.id"><Clock3 :size="19" class="text-primary"/><div><b>{{ m.home_club_name }} vs {{ m.away_club_name }}</b><p>{{ m.competition_name }} · {{ date(m.scheduled_at,true) }}</p></div><StatusBadge :status="m.status"/></article></div></section><section class="glass card"><div class="section-title"><div><span class="eyebrow">Thành tích</span><h2>Danh hiệu CLB</h2></div></div><EmptyState v-if="!data.achievements.length"/><div v-else class="compact-list"><article v-for="a in data.achievements" :key="a.id"><div class="medal">{{ Number(a.placement)===1?'🥇':Number(a.placement)===2?'🥈':'🥉' }}</div><div><b>{{ a.competition_name }}</b><p>{{ a.season_name }} · Hạng {{ a.placement }}</p></div></article></div></section></div></template></template></div></template>
<style scoped>.dashboard-stats{display:grid;grid-template-columns:repeat(6,1fr);gap:14px;margin-bottom:20px}.dashboard-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}.compact-list,.rank-list,.transaction-list{display:grid}.compact-list article,.compact-list a,.rank-list article,.transaction-list article{display:grid;grid-template-columns:auto 1fr auto;align-items:center;gap:10px;padding:11px 5px;border-bottom:1px solid var(--line)}.compact-list article:last-child,.compact-list a:last-child,.rank-list article:last-child,.transaction-list article:last-child{border-bottom:0}.compact-list b,.rank-list b,.transaction-list b{font-size:13px}.compact-list p,.rank-list p,.transaction-list p{font-size:10px}.competition-icon,.tx-icon{width:38px;height:38px;border-radius:11px;display:grid;place-items:center;background:rgba(57,130,255,.1);color:#7daeff}.rank{width:29px;text-align:center;font-weight:800;color:var(--yellow)}.tx-icon.credit{color:var(--green);background:rgba(53,221,154,.09)}.tx-icon.debit{color:var(--red);background:rgba(255,93,115,.09)}.transaction-list strong{font-size:12px}.club-summary{padding:24px;display:grid;grid-template-columns:auto 1fr auto;align-items:center;gap:20px}.club-summary h2{font-size:29px;margin:5px 0}.club-rank{text-align:right}.club-rank small{display:block;color:var(--muted)}.club-rank b{display:block;font:800 35px Manrope;color:var(--yellow);margin:4px 0}.medal{font-size:28px}@media(max-width:1300px){.dashboard-stats{grid-template-columns:repeat(3,1fr)}}@media(max-width:800px){.dashboard-grid{grid-template-columns:1fr}.dashboard-stats{grid-template-columns:repeat(2,1fr)}.club-summary{grid-template-columns:auto 1fr}.club-rank{grid-column:1/-1;text-align:left}}@media(max-width:480px){.dashboard-stats{grid-template-columns:1fr 1fr}.stat-value{font-size:21px}}</style>
